/**
 * POST /api/orders/scan-bulk-update
 * Phase 3 — tách nguyên khối từ server.ts (không đổi logic).
 */
import { emitOrderUpdated } from "../services/orderRealtime.js";

const RETURN_SCAN_DUPLICATE_ERROR =
  "Đơn hàng này ĐÃ ĐƯỢC QUÉT XÁC NHẬN thu hồi trước đó!";

function readReturnReceivedFlag(order) {
  if (!order || typeof order !== "object") return { locked: false, receivedAt: null };
  const nested =
    order.internal_flags && typeof order.internal_flags === "object"
      ? order.internal_flags
      : null;
  const data = order.data && typeof order.data === "object" ? order.data : null;
  const dataNested =
    data?.internal_flags && typeof data.internal_flags === "object"
      ? data.internal_flags
      : null;
  const locked =
    order.isReturnReceived === true ||
    nested?.isReturnReceived === true ||
    data?.isReturnReceived === true ||
    dataNested?.isReturnReceived === true;
  const receivedAt =
    order.returnReceivedAt ||
    nested?.returnReceivedAt ||
    data?.returnReceivedAt ||
    dataNested?.returnReceivedAt ||
    null;
  return { locked, receivedAt };
}

function stampReturnReceived(order, at) {
  const receivedAt = at || new Date();
  order.isReturnReceived = true;
  order.returnReceivedAt = receivedAt;
  order.internal_flags = {
    ...(order.internal_flags && typeof order.internal_flags === "object"
      ? order.internal_flags
      : {}),
    isReturnReceived: true,
    returnReceivedAt: receivedAt,
  };
  return order;
}

/** Deps từ server.ts (order helpers / mongoStore chưa tách hết). */
let deps = {
  findOrderByScanCodeInStore: async () => null,
  findOrdersByScanCodesInStore: async () => new Map(),
  resolveOrderFromShopeeByScanCode: async () => null,
  isValidOrder: () => false,
  mirrorTrackingFieldsForRead: (o) => o,
  resolveOrderLocalStatus: () => "",
  existsDonHoanHuy: async () => false,
  existsDonHoanHuyMany: async () => new Set(),
  isShopeeCancelOrReturnLikeOrder: () => false,
  isOrderAlreadyScanProcessed: () => false,
  getScanProcessedReason: () => "",
  handOverOrderToCarrierByIndex: async () => ({ ok: false, error: "not_initialized" }),
  clearHandedOverLocalForCancelReturn: () => {},
  setOrderLocalStatus: () => {},
  ORDER_LOCAL_STATUS: { HANDED_OVER: "HANDED_OVER" },
  isEligibleForHandOverShared: () => false,
  isMongoReady: () => false,
  upsertDonHoanHuyBatch: async () => ({ ok: 0, failed: 0, errors: ["not_initialized"] }),
  markOrdersScanFlagsBatch: async () => 0,
  describeMongoWriteError: (err) => String(err?.message || err || ""),
  isMongoConnectionError: () => false,
  persistChangedOrdersPatch: async () => 0,
  markOrderHandedOverInStore: async () => false,
  markOrderLocalStatusInStore: async () => false,
  restoreLocalStockOnCancelReturnScan: async () => ({ restored: false }),
  restoreLocalStockOnCancelReturnScanBatch: async () => ({ restored: 0, qty: 0 }),
  loadProductsForOrders: async () => [],
  enrichOrdersFromCatalog: (orders) => orders,
  invalidateOrdersRefreshCache: () => {},
  applyHandedOverWrite: (order) => order,
  getHandOverIneligibleReasonShared: () => "",
};

export function initScanBulkController(partial) {
  deps = { ...deps, ...partial };
}

/** POST /api/orders/scan-bulk-update */
export async function scanBulkUpdate(req, res) {
  const __t0 = Date.now();
  const __timing = {};
  const __mark = (label) => {
    __timing[label] = Date.now() - __t0;
  };
  try {
    const rawCodes = Array.isArray(req.body?.codes)
      ? req.body.codes
      : Array.isArray(req.body?.scannedCodes)
        ? req.body.scannedCodes
        : Array.isArray(req.body?.scanCodes)
          ? req.body.scanCodes
          : [];
    const codes = [...new Set(rawCodes.map((c) => String(c || "").trim().toUpperCase()).filter(Boolean))];
    if (!codes.length) {
      return res.status(400).json({
        success: false,
        error: "Thiếu danh sách mã quét (codes).",
        message: "Thiếu danh sách mã quét (codes / scannedCodes).",
      });
    }

    const toCodeSet = (arr) => {
      if (!Array.isArray(arr)) return new Set();
      return new Set(arr.map((c) => String(c || "").trim().toUpperCase()).filter(Boolean));
    };
    const forceHandOverCodes = toCodeSet(req.body?.daXuatKhoCodes);
    const forceCancelCodes = toCodeSet(req.body?.donHuyCodes);
    const forceReturnCodes = toCodeSet(req.body?.daNhanHoanCodes);

    // Lookup Mongo exact $eq `$in` — 1 query. KHÔNG gọi Shopee. KHÔNG N lần findOne.
    let foundByCode = new Map();
    try {
      foundByCode = await deps.findOrdersByScanCodesInStore(codes);
    } catch (batchLookupErr) {
      console.warn(
        "[Orders Scan Bulk] batch lookup fail:",
        batchLookupErr?.message || batchLookupErr,
      );
    }
    __mark("lookup");

    const lookupPairs = codes.map((code) => {
      const scannedCode = String(code || "").trim().toUpperCase();
      let found = foundByCode.get(code) || foundByCode.get(scannedCode) || null;
      try {
        if (found && !deps.isValidOrder(found)) found = null;
        if (found) found = deps.mirrorTrackingFieldsForRead(found);
      } catch (lookupErr) {
        console.warn(
          `[Orders Scan Bulk] hydrate miss code=${scannedCode}:`,
          lookupErr?.message || lookupErr,
        );
        found = null;
      }
      return { code: scannedCode, found };
    });

    if (lookupPairs.every((p) => !p.found)) {
      return res.status(404).json({
        success: false,
        message: "Không tìm thấy mã trên hệ thống",
        notFound: true,
      });
    }

    const orders = [];
    const orderIndexById = new Map();
    const putScoped = (order) => {
      if (!order?.id) return -1;
      const existing = orderIndexById.get(String(order.id));
      if (existing !== undefined) return existing;
      const idx = orders.length;
      orders.push(order);
      orderIndexById.set(String(order.id), idx);
      return idx;
    };
    for (const pair of lookupPairs) {
      if (pair.found) putScoped(pair.found);
    }

    const results = [];
    const failed_scans = [];
    const changedOrders = [];
    const updatedById = new Map();
    /** Restock tồn local — chạy nền sau response. */
    const restockJobsDeferred = [];
    /** Chỉ đếm record THỰC SỰ vừa UPDATE thành công trong DB. */
    const summary = { daXuatKho: 0, donHuy: 0, daNhanHoan: 0 };
    /** Số đơn hủy/hoàn đã có sẵn trong don_hoan_huy (idempotent). */
    let donHoanHuyAlready = 0;
    /** orderSn hủy/hoàn đã chốt trong request — chặn quét trùng cùng lô. */
    const returnScanSeen = new Set();
    /** Đơn đã nằm don_hoan_huy nhưng thiếu cờ — chỉ backfill cờ, không restock. */
    const returnFlagBackfill = [];

    const norm = (c) => String(c || "").trim().toUpperCase();

    // Chỉ cần check don_hoan_huy khi lô CÓ khả năng đụng hủy/hoàn — lô "xuất kho" thuần
    // (chỉ daXuatKhoCodes, không có mã/order hủy-hoàn nào) bỏ hẳn round-trip này.
    const mightHaveCancelReturn =
      forceCancelCodes.size > 0 ||
      forceReturnCodes.size > 0 ||
      orders.some((o) => {
        const status = String(o?.status || "");
        const rawShopee = String(o?.shopee_order_status || "").toUpperCase();
        if (status === "return_pending" || status === "return_received" || rawShopee === "TO_RETURN") {
          return true;
        }
        return (
          status === "cancelled" ||
          rawShopee === "CANCELLED" ||
          rawShopee === "IN_CANCEL" ||
          Boolean(deps.isShopeeCancelOrReturnLikeOrder(o))
        );
      });

    let alreadyInDonHoanHuySet = new Set();
    if (mightHaveCancelReturn) {
      // Prefetch exists don_hoan_huy — 1 query $in thay vì N findOne.
      const snsForExists = [
        ...new Set(
          lookupPairs
            .map((p) => String(p.found?.orderSn || "").replace(/^shopee-/i, "").trim())
            .filter(Boolean),
        ),
      ];
      try {
        alreadyInDonHoanHuySet = await deps.existsDonHoanHuyMany(snsForExists);
      } catch {
        alreadyInDonHoanHuySet = new Set();
      }
    }
    __mark("existsCheck");

    /** Handover batch — gom cờ qua changedOrders → markOrdersScanFlagsBatch 1 lần. */

    for (const { code, found } of lookupPairs) {
      const codeKey = norm(code);
      if (!found) {
        results.push({
          code,
          action: "not_found",
          message: "Không tìm thấy mã trên hệ thống",
          notFound: true,
        });
        failed_scans.push({
          code,
          reason: "Không tìm thấy mã trên hệ thống",
          notFound: true,
        });
        continue;
      }

      const index = putScoped(found);
      if (index < 0) {
        results.push({
          code,
          action: "not_found",
          message: "Không tìm thấy mã trên hệ thống",
          notFound: true,
        });
        failed_scans.push({
          code,
          reason: "Không tìm thấy mã trên hệ thống",
          notFound: true,
        });
        continue;
      }

      const order = orders[index];
      const status = String(order.status || "");
      const rawShopee = String(order.shopee_order_status || "").toUpperCase();
      const existingLocal = deps.resolveOrderLocalStatus(order);
      const orderSnNorm = String(order.orderSn || "").replace(/^shopee-/i, "").trim();
      const alreadyInDonHoanHuy = alreadyInDonHoanHuySet.has(orderSnNorm);
      const forceHandOver =
        forceHandOverCodes.has(codeKey) ||
        forceHandOverCodes.has(norm(String(order.orderSn || ""))) ||
        forceHandOverCodes.has(norm(String(order.trackingNumber || order.tracking_no || "")));
      const forceCancel =
        forceCancelCodes.has(codeKey) ||
        forceCancelCodes.has(norm(String(order.orderSn || ""))) ||
        forceCancelCodes.has(norm(String(order.trackingNumber || order.tracking_no || ""))) ||
        forceCancelCodes.has(norm(String(order.return_tracking_no || order.returnTrackingNumber || "")));
      const forceReturn =
        forceReturnCodes.has(codeKey) ||
        forceReturnCodes.has(norm(String(order.orderSn || ""))) ||
        forceReturnCodes.has(norm(String(order.trackingNumber || order.tracking_no || ""))) ||
        forceReturnCodes.has(norm(String(order.return_tracking_no || order.returnTrackingNumber || "")));
      const isReturnLike =
        status === "return_pending" ||
        status === "return_received" ||
        rawShopee === "TO_RETURN";
      const isCancelLike =
        !isReturnLike &&
        (status === "cancelled" ||
          rawShopee === "CANCELLED" ||
          rawShopee === "IN_CANCEL" ||
          deps.isShopeeCancelOrReturnLikeOrder(order));

      // Chốt chặn quét trùng CHỈ luồng xác nhận hủy/hoàn. Bàn giao ĐVVC không đi vào nhánh này.
      const isCancelReturnConfirm = (forceCancel || forceReturn) && !forceHandOver;
      if (isCancelReturnConfirm) {
        const receivedFlag = readReturnReceivedFlag(order);
        const seenKey = orderSnNorm || codeKey;
        if (receivedFlag.locked || alreadyInDonHoanHuy || returnScanSeen.has(seenKey)) {
          if (!returnScanSeen.has(seenKey)) {
            returnScanSeen.add(seenKey);
            if (!receivedFlag.locked && orderSnNorm) {
              returnFlagBackfill.push({
                orderSn: orderSnNorm,
                localStatus: forceReturn ? "RETURN_RECEIVED" : "CANCELLED_STORED",
                shopId: order?.shopId != null ? String(order.shopId) : undefined,
              });
              donHoanHuyAlready += 1;
            }
            results.push({
              code,
              action: "duplicate",
              orderId: order.id,
              orderSn: order.orderSn,
              message: RETURN_SCAN_DUPLICATE_ERROR,
              error: RETURN_SCAN_DUPLICATE_ERROR,
              receivedAt: receivedFlag.receivedAt,
              local_status: existingLocal || (forceReturn ? "RETURN_RECEIVED" : "CANCELLED_STORED"),
            });
            failed_scans.push({
              code,
              orderId: order.id,
              orderSn: order.orderSn,
              reason: RETURN_SCAN_DUPLICATE_ERROR,
              error: RETURN_SCAN_DUPLICATE_ERROR,
              receivedAt: receivedFlag.receivedAt,
              duplicateReturn: true,
            });
          }
          continue;
        }
        returnScanSeen.add(seenKey);
      }
      const allowForceCancelReturnOverride =
        (forceCancel || forceReturn) &&
        (existingLocal === "HANDED_OVER" ||
          existingLocal === "CANCELLED_STORED" ||
          existingLocal === "RETURN_RECEIVED" ||
          isCancelLike ||
          isReturnLike);
      // Đã xử lý ĐVVC thuần — chặn; còn force hủy/hoàn thì vẫn ghi don_hoan_huy.
      if (
        deps.isOrderAlreadyScanProcessed(order) &&
        !allowForceCancelReturnOverride &&
        !forceCancel &&
        !forceReturn
      ) {
        const reason = deps.getScanProcessedReason(order);
        results.push({
          code,
          action: "duplicate",
          orderId: order.id,
          orderSn: order.orderSn,
          message: reason,
          local_status: existingLocal,
        });
        failed_scans.push({
          code,
          orderId: order.id,
          orderSn: order.orderSn,
          reason,
        });
        continue;
      }

      // FE phân loại xuất kho (chỉ Chờ lấy hàng đã xử lý) → WRITE HANDED_OVER (bulk cuối).
      if (forceHandOver) {
        const alreadyHanded =
          existingLocal === "HANDED_OVER" ||
          order.is_handed_over === true ||
          order.isHandedOverToCarrier === true;
        if (alreadyHanded) {
          summary.daXuatKho += 1;
          results.push({
            code,
            action: "handed_over",
            orderId: order.id,
            orderSn: order.orderSn,
            message: `Đơn #${order.orderSn} đã có cờ ĐVVC`,
            local_status: deps.ORDER_LOCAL_STATUS.HANDED_OVER,
          });
          continue;
        }
        // FE đã phân loại xuất kho — tin daXuatKhoCodes, không reject vì thiếu tracking/shop lệch.
        const sn = String(order.orderSn || "").replace(/^shopee-/i, "").trim();
        if (!sn) {
          results.push({
            code,
            action: "rejected",
            orderId: order.id,
            orderSn: order.orderSn,
            message: "Thiếu orderSn — không ghi bàn giao ĐVVC",
            local_status: existingLocal,
          });
          failed_scans.push({
            code,
            orderId: order.id,
            orderSn: order.orderSn,
            reason: "Thiếu orderSn",
          });
          continue;
        }
        const updated = deps.applyHandedOverWrite
          ? deps.applyHandedOverWrite({ ...order }, undefined, "qr_scan")
          : {
              ...order,
              is_handed_over: true,
              isHandedOverToCarrier: true,
              local_status: "HANDED_OVER",
              localStatus: "HANDED_OVER",
            };
        orders[index] = updated;
        changedOrders.push(updated);
        updatedById.set(updated.id, updated);
        summary.daXuatKho += 1;
        results.push({
          code,
          action: "handed_over",
          orderId: updated.id,
          orderSn: updated.orderSn,
          message: `Đã bàn giao ĐVVC — đơn #${updated.orderSn}`,
          local_status: deps.ORDER_LOCAL_STATUS.HANDED_OVER,
        });
        continue;
      }

      // FE / raw Shopee: nhận hoàn (kể cả sau HANDED_OVER).
      if (forceReturn || isReturnLike) {
        const finalSn = String(order.orderSn || "").replace(/^shopee-/i, "").trim();
        if (
          !finalSn ||
          /^(SPX(VN)?|GHN|GYA|GHTK|JNT|JT|NINJA|VTP|VNPOST|BEST|LEX)/i.test(finalSn)
        ) {
          results.push({
            code,
            action: "not_found",
            message: `Mã "${code}" chưa resolve được order_sn Shopee — không lưu đơn giả.`,
          });
          failed_scans.push({
            code,
            reason: "Thiếu order_sn thật sau khi gọi Shopee",
          });
          continue;
        }
        if (!Array.isArray(order.items) || order.items.length === 0) {
          results.push({
            code,
            action: "rejected",
            orderId: order.id,
            orderSn: order.orderSn,
            message: `Đơn #${order.orderSn} thiếu danh sách sản phẩm — không lưu.`,
          });
          failed_scans.push({
            code,
            orderSn: order.orderSn,
            reason: "Thiếu items",
          });
          continue;
        }
        const wasHandedOver =
          existingLocal === "HANDED_OVER" ||
          order.is_handed_over === true ||
          order.isHandedOverToCarrier === true;
        const updated = { ...order };
        deps.clearHandedOverLocalForCancelReturn(updated);
        deps.setOrderLocalStatus(updated, "RETURN_RECEIVED");
        stampReturnReceived(updated);
        restockJobsDeferred.push({ order: updated, wasHandedOver });
        orders[index] = updated;
        changedOrders.push(updated);
        updatedById.set(updated.id, updated);
        summary.daNhanHoan += 1;
        results.push({
          code,
          action: "return_received",
          orderId: updated.id,
          orderSn: updated.orderSn,
          message: `Đã nhận hàng hoàn — đơn #${updated.orderSn}`,
          local_status: "RETURN_RECEIVED",
          stock_restored: Boolean(updated.stock_restored),
        });
        continue;
      }

      // FE / raw Shopee: đơn hủy (CANCELLED / IN_CANCEL), kể cả sau HANDED_OVER.
      if (forceCancel || isCancelLike) {
        const finalSn = String(order.orderSn || "").replace(/^shopee-/i, "").trim();
        if (
          !finalSn ||
          /^(SPX(VN)?|GHN|GYA|GHTK|JNT|JT|NINJA|VTP|VNPOST|BEST|LEX)/i.test(finalSn)
        ) {
          results.push({
            code,
            action: "not_found",
            message: `Mã "${code}" chưa resolve được order_sn Shopee — không lưu đơn giả.`,
          });
          failed_scans.push({
            code,
            reason: "Thiếu order_sn thật sau khi gọi Shopee",
          });
          continue;
        }
        if (!Array.isArray(order.items) || order.items.length === 0) {
          results.push({
            code,
            action: "rejected",
            orderId: order.id,
            orderSn: order.orderSn,
            message: `Đơn #${order.orderSn} thiếu danh sách sản phẩm — không lưu.`,
          });
          failed_scans.push({
            code,
            orderSn: order.orderSn,
            reason: "Thiếu items",
          });
          continue;
        }
        const wasHandedOver =
          existingLocal === "HANDED_OVER" ||
          order.is_handed_over === true ||
          order.isHandedOverToCarrier === true;
        const updated = { ...order };
        if (updated.status !== "cancelled") updated.status = "cancelled";
        deps.clearHandedOverLocalForCancelReturn(updated);
        deps.setOrderLocalStatus(updated, "CANCELLED_STORED");
        stampReturnReceived(updated);
        restockJobsDeferred.push({ order: updated, wasHandedOver });
        orders[index] = updated;
        changedOrders.push(updated);
        updatedById.set(updated.id, updated);
        summary.donHuy += 1;
        results.push({
          code,
          action: "cancelled",
          orderId: updated.id,
          orderSn: updated.orderSn,
          message: `Đơn hủy #${updated.orderSn} → CANCELLED_STORED`,
          local_status: "CANCELLED_STORED",
          stock_restored: Boolean(updated.stock_restored),
        });
        continue;
      }

      // Không có phân loại FE: chỉ bàn giao nếu đúng Chờ lấy hàng (đã xử lý).
      if (deps.isEligibleForHandOverShared(order)) {
        const result = await deps.handOverOrderToCarrierByIndex(orders, index, {
          persist: false,
          source: "qr_scan",
        });
        if (!result.ok) {
          results.push({
            code,
            action: "rejected",
            orderId: order.id,
            orderSn: order.orderSn,
            message: result.error,
            local_status: existingLocal,
          });
          failed_scans.push({
            code,
            orderId: order.id,
            orderSn: order.orderSn,
            reason: result.error,
          });
          continue;
        }
        if (result.changed) {
          changedOrders.push(result.order);
          updatedById.set(result.order.id, result.order);
          summary.daXuatKho += 1;
        }
        results.push({
          code,
          action: "handed_over",
          orderId: result.order.id,
          orderSn: result.order.orderSn,
          message: `Đã bàn giao ĐVVC — đơn #${result.order.orderSn}`,
          local_status: deps.ORDER_LOCAL_STATUS.HANDED_OVER,
        });
        continue;
      }

      results.push({
        code,
        action: "skipped",
        orderId: order.id,
        orderSn: order.orderSn,
        message: `Đơn #${order.orderSn} không thuộc Chờ lấy hàng (đã xử lý) / Đơn hủy — bỏ qua`,
      });
      failed_scans.push({
        code,
        orderId: order.id,
        orderSn: order.orderSn,
        reason: `Trạng thái "${status}" không thuộc quy tắc quét ĐVVC`,
      });
    }

    // Restock tồn local — chạy nền sau khi trả response (không block quét).
    const runRestockBackground = (jobs) => {
      if (!jobs.length) return;
      if (typeof deps.restoreLocalStockOnCancelReturnScanBatch !== "function") return;
      void deps
        .restoreLocalStockOnCancelReturnScanBatch(jobs)
        .then((restock) => {
          if (restock?.restored) {
            console.log(
              `[Orders Scan Bulk] Restock BG +${restock.qty || 0} tồn / ${restock.restored} đơn`,
            );
          }
        })
        .catch((restockErr) => {
          console.warn(
            "[Orders Scan Bulk] Restock BG fail:",
            restockErr?.message || restockErr,
          );
        });
    };

    __mark("classify");
    // Persist: hủy/hoàn → collection don_hoan_huy (SSOT tab);
    // xuất kho → markOrdersScanFlagsBatch. Không phụ thuộc order_events. Không gọi Shopee.
    const scanCodeByOrderSn = new Map();
    for (const r of results) {
      const sn = String(r?.orderSn || "").replace(/^shopee-/i, "").trim();
      if (sn && r?.code) scanCodeByOrderSn.set(sn, String(r.code));
    }
    const cancelReturnRows = [];
    for (const o of changedOrders) {
      const local = String(
        o?.local_status || o?.localStatus || o?.internal_status || "",
      ).toUpperCase();
      const sn = String(o?.orderSn || "").replace(/^shopee-/i, "").trim();
      if (local === "CANCELLED_STORED") {
        cancelReturnRows.push({
          order: o,
          type: "cancelled",
          scanCode: scanCodeByOrderSn.get(sn),
        });
      } else if (local === "RETURN_RECEIVED") {
        cancelReturnRows.push({
          order: o,
          type: "return",
          scanCode: scanCodeByOrderSn.get(sn),
        });
      }
    }

    let donHoanHuyWrite = {
      ok: 0,
      failed: 0,
      errors: [],
    };
    if (cancelReturnRows.length > 0) {
      if (!deps.isMongoReady()) {
        console.error("[Orders Scan Bulk] Mongo not ready — không ghi được don_hoan_huy");
        return res.status(500).json({
          success: false,
          message: "Lỗi kết nối MongoDB",
          error: "mongodb_not_ready",
        });
      }
      try {
        donHoanHuyWrite = await deps.upsertDonHoanHuyBatch(
          cancelReturnRows.map((r) => ({
            order: r.order,
            type: r.type,
            scanCode: r.scanCode,
            source: "qr_scan",
          })),
        );
      } catch (dhhErr) {
        console.error("[Orders Scan Bulk] don_hoan_huy batch FAIL:", dhhErr);
        const detail = deps.describeMongoWriteError(dhhErr);
        return res.status(500).json({
          success: false,
          message: deps.isMongoConnectionError(dhhErr) ? "Lỗi kết nối MongoDB" : detail,
          error: "don_hoan_huy_write_failed",
        });
      }
      if (donHoanHuyWrite.failed > 0 && donHoanHuyWrite.ok === 0) {
        const detail =
          donHoanHuyWrite.errors[0] ||
          "Không ghi được đơn nào vào collection don_hoan_huy.";
        console.error("[Orders Scan Bulk] don_hoan_huy all failed:", donHoanHuyWrite.errors);
        const connFail = /Lỗi kết nối MongoDB/i.test(detail);
        return res.status(500).json({
          success: false,
          message: connFail ? "Lỗi kết nối MongoDB" : detail,
          error: "don_hoan_huy_write_failed",
          errors: donHoanHuyWrite.errors.slice(0, 10),
        });
      }
    }
    __mark("donHoanHuyWrite");

    let flagWriteError = null;
    let flagOk = 0;
    const flagRows = [];
    if (changedOrders.length > 0) {
      for (const o of changedOrders) {
        const sn = String(o?.orderSn || "").replace(/^shopee-/i, "").trim();
        if (!sn) continue;
        const shopId = o?.shopId != null ? String(o.shopId) : undefined;
        const local = String(
          o?.local_status || o?.localStatus || o?.internal_status || "",
        ).toUpperCase();
        if (
          local === "HANDED_OVER" ||
          o?.is_handed_over === true ||
          o?.isHandedOverToCarrier === true
        ) {
          flagRows.push({
            orderSn: sn,
            localStatus: "HANDED_OVER",
            shopId,
            source: "qr_scan",
            handedOverAt: String(o.handedOverAt || new Date().toISOString()),
          });
        } else if (local === "CANCELLED_STORED" || local === "RETURN_RECEIVED") {
          flagRows.push({
            orderSn: sn,
            localStatus: local,
            shopId,
            stockRestored: Boolean(o.stock_restored),
            stockRestoredAt: o.stock_restored_at
              ? String(o.stock_restored_at)
              : undefined,
          });
        }
      }
    }
    for (const row of returnFlagBackfill) {
      if (!row?.orderSn) continue;
      flagRows.push({
        orderSn: row.orderSn,
        localStatus: row.localStatus,
        shopId: row.shopId,
      });
    }
    if (flagRows.length > 0 || changedOrders.length > 0) {
      if (flagRows.length > 0) {
        try {
          flagOk = await deps.markOrdersScanFlagsBatch(flagRows);
        } catch (flagBatchErr) {
          flagWriteError = deps.describeMongoWriteError(flagBatchErr);
          console.error(
            "[Orders Scan Bulk] markOrdersScanFlagsBatch FAIL:",
            flagWriteError,
            flagBatchErr,
          );
        }
        if ((flagWriteError || flagOk === 0) && typeof deps.markOrderHandedOverInStore === "function") {
          let recovered = 0;
          const leftover = [];
          for (const row of flagRows) {
            try {
              if (row.localStatus === "HANDED_OVER") {
                const ok = await deps.markOrderHandedOverInStore(row.orderSn, {
                  source: row.source || "qr_scan",
                  handedOverAt: row.handedOverAt,
                  shopId: row.shopId,
                });
                if (ok) recovered += 1;
                else leftover.push(row.orderSn);
              } else if (typeof deps.markOrderLocalStatusInStore === "function") {
                const ok = await deps.markOrderLocalStatusInStore(row.orderSn, row.localStatus, {
                  shopId: row.shopId,
                  stockRestored: row.stockRestored,
                  stockRestoredAt: row.stockRestoredAt,
                });
                if (ok) recovered += 1;
                else leftover.push(row.orderSn);
              } else {
                leftover.push(row.orderSn);
              }
            } catch (oneErr) {
              leftover.push(row.orderSn);
              console.error(
                "[Orders Scan Bulk] fallback flag write fail:",
                row.orderSn,
                oneErr?.message || oneErr,
              );
            }
          }
          if (recovered > 0) {
            flagOk = recovered;
            if (leftover.length === 0) flagWriteError = null;
            else {
              flagWriteError = `Một phần đơn chưa ghi được cờ: ${leftover.slice(0, 8).join(", ")}`;
            }
            console.warn(
              `[Orders Scan Bulk] fallback markOrderHandedOver recovered=${recovered} leftover=${leftover.length}`,
            );
          }
        }
      }
      console.log(
        `[Orders Scan Bulk] don_hoan_huy ok=${donHoanHuyWrite.ok} fail=${donHoanHuyWrite.failed}` +
          ` handoverFlags=${flagOk} changed=${changedOrders.length}` +
          (flagWriteError ? ` flagError=${flagWriteError}` : ""),
      );
      deps.invalidateOrdersRefreshCache();
    }
    __mark("flagWrite");

    runRestockBackground(restockJobsDeferred);

    const updatedList = [...updatedById.values()];
    const processedCount = summary.daXuatKho + summary.donHuy + summary.daNhanHoan;
    const partialFailure = Boolean(flagWriteError);
    const responsePayload = {
      success: !partialFailure,
      partialFailure,
      processedCount,
      persistedCount: changedOrders.length,
      donHoanHuy: {
        ...donHoanHuyWrite,
        already: donHoanHuyAlready,
        ensured: donHoanHuyWrite.ok + donHoanHuyAlready,
      },
      summary,
      stats: {
        handedOver: summary.daXuatKho,
        cancelled: summary.donHuy,
        returnReceived: summary.daNhanHoan,
        notFound: failed_scans.filter((f) => f.reason.includes("Không tìm thấy")).length,
        skipped: results.filter((r) => r.action === "skipped").length,
        duplicates: results.filter((r) => r.action === "duplicate").length,
      },
      results,
      failed_scans,
      orders: updatedList,
    };

    const duplicateReturns = failed_scans.filter((f) => f.duplicateReturn);
    const duplicateOnly =
      processedCount === 0 && duplicateReturns.length > 0 && changedOrders.length === 0;
    if (duplicateOnly) {
      return res.status(400).json({
        ...responsePayload,
        success: false,
        partialFailure: false,
        error: RETURN_SCAN_DUPLICATE_ERROR,
        message: RETURN_SCAN_DUPLICATE_ERROR,
        receivedAt: duplicateReturns[0]?.receivedAt || null,
      });
    }

    if (partialFailure) {
      return res.status(500).json({
        ...responsePayload,
        message: `Ghi cờ phân loại thất bại: ${flagWriteError}`,
        error: "scan_flags_batch_failed",
      });
    }

    console.log(
      `[Orders Scan Bulk] PERSISTED codes=${codes.length} updated=${changedOrders.length} summary=${JSON.stringify(summary)} failed=${failed_scans.length} mongo=${deps.isMongoReady()}` +
        ` timing_ms=${JSON.stringify(__timing)} total=${Date.now() - __t0}ms skippedExistsCheck=${!mightHaveCancelReturn}`,
    );

    // Realtime sync: báo các client khác (PC) refetch NGẦM sau khi quét trên máy/điện thoại khác.
    if (updatedList.length > 0) {
      try {
        emitOrderUpdated({
          orderSns: updatedList
            .map((o) => String(o?.orderSn || "").trim())
            .filter(Boolean),
          shopIds: [
            ...new Set(
              updatedList.map((o) => String(o?.shopId || "").trim()).filter(Boolean),
            ),
          ],
          count: updatedList.length,
        });
      } catch (emitErr) {
        console.warn(
          "[Orders Scan Bulk] emitOrderUpdated fail:",
          emitErr?.message || emitErr,
        );
      }
    }

    return res.json(responsePayload);
  } catch (error) {
    console.error("[Orders Scan Bulk] Error:", error);
    const detail = deps.describeMongoWriteError(error);
    return res.status(500).json({
      success: false,
      partialFailure: false,
      message: deps.isMongoConnectionError(error)
        ? "Lỗi kết nối MongoDB"
        : detail || "Không thể cập nhật hàng loạt đơn đã quét.",
      error: error?.message || "scan_bulk_update_failed",
    });
  }
}
