/**
 * Kho Gốc trên đĩa hosting (data/products.json) — không dùng Mongo Atlas.
 * Bật bằng PRODUCTS_STORAGE=disk | json | file
 */
import fs from "fs";
import path from "path";
import {
  normalizeProductSearchText,
  productRowMatchesSearch,
} from "../utils/productSearch.ts";

export function isProductsDiskMode(): boolean {
  // Mặc định disk (hosting) — Atlas free dễ đầy. Set PRODUCTS_STORAGE=mongo để dùng Atlas.
  const raw = process.env.PRODUCTS_STORAGE ?? process.env.PRODUCTS_DISK;
  if (raw == null || String(raw).trim() === "") return true;
  const v = String(raw).trim().toLowerCase();
  if (v === "mongo" || v === "atlas" || v === "0" || v === "false" || v === "off") {
    return false;
  }
  return (
    v === "disk" ||
    v === "json" ||
    v === "file" ||
    v === "1" ||
    v === "true" ||
    v === "on"
  );
}

let appRootResolved = "";
let productsCache: { mtimeMs: number; products: any[] } | null = null;
let writeChain: Promise<void> = Promise.resolve();

export function setProductsDiskAppRoot(appRoot: string): void {
  appRootResolved = String(appRoot || "").trim();
}

function resolveAppRoot(): string {
  if (appRootResolved) return appRootResolved;
  return process.cwd();
}

export function getProductsDiskPath(): string {
  return path.join(resolveAppRoot(), "data", "products.json");
}

function ensureDataDir(): void {
  const dir = path.dirname(getProductsDiskPath());
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function normalizeProduct(p: any): any | null {
  if (!p || typeof p !== "object") return null;
  const id = String(p.id || "").trim();
  if (!id) return null;
  return { ...p, id };
}

/** Child kế thừa shopeeItemId / channels từ parent nếu thiếu (để sync stock/price không mất Mapping). */
export function inheritShopeeLinkFromParent(child: any, parent: any): any {
  if (!child || typeof child !== "object") return child;
  if (!parent || typeof parent !== "object") return child;
  const next = { ...child };
  if (!next.shopeeItemId && parent.shopeeItemId) next.shopeeItemId = parent.shopeeItemId;
  if (!next.shopeeId && parent.shopeeId) next.shopeeId = parent.shopeeId;
  if (!next.channels?.length && Array.isArray(parent.channels) && parent.channels.length) {
    next.channels = [...parent.channels];
  }
  if (!next.title && parent.title) next.title = parent.title;
  if (!next.imageUrl && parent.imageUrl) next.imageUrl = parent.imageUrl;
  if (!next.avatarUrl && parent.avatarUrl) next.avatarUrl = parent.avatarUrl;
  return next;
}

export function readProductsFromDisk(): any[] {
  const file = getProductsDiskPath();
  if (!fs.existsSync(file)) {
    productsCache = { mtimeMs: 0, products: [] };
    return [];
  }
  const st = fs.statSync(file);
  if (productsCache && productsCache.mtimeMs === st.mtimeMs) {
    return productsCache.products;
  }
  try {
    const raw = fs.readFileSync(file, "utf-8");
    const parsed = raw.trim() ? JSON.parse(raw) : [];
    const products = (Array.isArray(parsed) ? parsed : [])
      .map(normalizeProduct)
      .filter(Boolean) as any[];
    productsCache = { mtimeMs: st.mtimeMs, products };
    return products;
  } catch (err: any) {
    console.error("[Products Disk] Đọc products.json thất bại:", err?.message || err);
    throw err instanceof Error ? err : new Error(String(err));
  }
}

function writeProductsToDiskSync(products: any[]): void {
  ensureDataDir();
  const file = getProductsDiskPath();
  const list = (Array.isArray(products) ? products : [])
    .map(normalizeProduct)
    .filter(Boolean)
    .map((p) => stampInventorySortFields(p)) as any[];
  const tmp = `${file}.tmp.${process.pid}`;
  fs.writeFileSync(tmp, JSON.stringify(list), "utf-8");
  fs.renameSync(tmp, file);
  try {
    const st = fs.statSync(file);
    productsCache = { mtimeMs: st.mtimeMs, products: list };
  } catch {
    productsCache = { mtimeMs: Date.now(), products: list };
  }
  console.log(`[Products Disk] WRITE OK — path=${file} count=${list.length}`);
}

export async function saveProductsToDisk(products: any[]): Promise<void> {
  const run = writeChain.then(() => {
    writeProductsToDiskSync(products);
  });
  writeChain = run.catch(() => undefined);
  await run;
}

export async function upsertProductsToDisk(products: any[]): Promise<number> {
  const incoming = (Array.isArray(products) ? products : [])
    .map(normalizeProduct)
    .filter(Boolean) as any[];
  if (incoming.length === 0) return 0;
  const current = readProductsFromDisk();
  const byId = new Map(current.map((p) => [String(p.id), p]));
  for (const p of incoming) byId.set(String(p.id), { ...byId.get(String(p.id)), ...p, id: p.id });
  await saveProductsToDisk([...byId.values()]);
  return incoming.length;
}

const SKU_CHILD_KEYS = ["children", "children_models"] as const;

/**
 * Chỉ đổi field `sku` của đúng sản phẩm (cha hoặc phân loại).
 * Không ghi đè shopeeItemId / shopeeModelId / mapping sàn.
 */
export async function updateProductSkuOnDisk(
  productId: string,
  newSku: string,
): Promise<{ found: boolean; sku: string; target: "parent" | "child" | null }> {
  const id = String(productId || "").trim();
  const sku = String(newSku || "").trim();
  if (!id || !sku) return { found: false, sku, target: null };

  const current = readProductsFromDisk();
  let found = false;
  let target: "parent" | "child" | null = null;
  const next: any[] = [];

  for (const product of current) {
    if (found) {
      next.push(product);
      continue;
    }
    if (String(product?.id || "").trim() === id) {
      found = true;
      target = "parent";
      next.push({ ...product, sku });
      continue;
    }
    let childKey: (typeof SKU_CHILD_KEYS)[number] | null = null;
    let childIdx = -1;
    for (const key of SKU_CHILD_KEYS) {
      const list = product?.[key];
      if (!Array.isArray(list)) continue;
      const idx = list.findIndex((child: any) => String(child?.id || "").trim() === id);
      if (idx >= 0) {
        childKey = key;
        childIdx = idx;
        break;
      }
    }
    if (childKey && childIdx >= 0) {
      found = true;
      target = "child";
      const list = product[childKey] as any[];
      const children = list.map((child, index) =>
        index === childIdx ? { ...child, sku } : child,
      );
      next.push({ ...product, [childKey]: children });
      continue;
    }
    next.push(product);
  }

  if (!found) return { found: false, sku, target: null };
  await saveProductsToDisk(next);
  return { found: true, sku, target };
}

export async function deleteProductsByIdsFromDisk(ids: string[]): Promise<number> {
  const safe = new Set(ids.map((id) => String(id || "").trim()).filter(Boolean));
  if (safe.size === 0) return 0;
  const current = readProductsFromDisk();
  const kept = current.filter((p) => !safe.has(String(p.id || "").trim()));
  const deleted = current.length - kept.length;
  if (deleted > 0) await saveProductsToDisk(kept);
  return deleted;
}

export function countProductsOnDisk(): number {
  return readProductsFromDisk().length;
}

export type InventoryListSort = {
  sortBy?: string;
  order?: string;
};

function variationRows(product: any): any[] {
  for (const key of ["children", "children_models", "models", "variations"] as const) {
    const list = product?.[key];
    if (Array.isArray(list) && list.length > 0) return list;
  }
  return [];
}

function readPrice(row: any): number {
  const n = Number(row?.sellingPrice ?? row?.price ?? row?.original_price);
  return Number.isFinite(n) ? n : 0;
}

function readStock(row: any): number {
  const n = Number(row?.stock ?? row?.current_stock ?? row?.normal_stock);
  return Number.isFinite(n) ? n : 0;
}

/** Giá thấp nhất và tổng tồn — sản phẩm đơn lấy root, có phân loại lấy trong mảng biến thể. */
export function inventorySortMetrics(product: any): { min_price: number; total_stock: number } {
  const rows = variationRows(product);
  if (rows.length === 0) {
    return { min_price: readPrice(product), total_stock: readStock(product) };
  }
  let min = Infinity;
  let stock = 0;
  for (let i = 0; i < rows.length; i++) {
    const price = readPrice(rows[i]);
    if (price < min) min = price;
    stock += readStock(rows[i]);
  }
  return { min_price: Number.isFinite(min) ? min : 0, total_stock: stock };
}

/** Ghi min_price / total_stock lên root trước khi lưu, để sort không phụ thuộc cấu trúc phân loại. */
export function stampInventorySortFields(product: any): any {
  if (!product || typeof product !== "object") return product;
  try {
    const metrics = inventorySortMetrics(product);
    product.min_price = metrics.min_price;
    product.total_stock = metrics.total_stock;
  } catch (err) {
    console.warn("[Inventory Sort] stamp failed:", err instanceof Error ? err.message : err);
  }
  return product;
}

/** Khớp cột Tồn kho / Giá bán: tổng tồn phân loại, hoặc giá bán thấp nhất. */
export function inventorySortValue(product: any, sortBy: "stock" | "sellingPrice"): number {
  const metrics = inventorySortMetrics(product);
  return sortBy === "stock" ? metrics.total_stock : metrics.min_price;
}

function normalizeInventoryListSort(
  sort?: InventoryListSort | null,
): { sortBy: "stock" | "sellingPrice"; order: "asc" | "desc" } | null {
  const sortBy = sort?.sortBy === "stock" || sort?.sortBy === "sellingPrice" ? sort.sortBy : "";
  const order = sort?.order === "asc" || sort?.order === "desc" ? sort.order : "";
  if (!sortBy || !order) return null;
  return { sortBy, order };
}

/** Sort bản sao — không đụng mảng cache products.json. */
function sortInventoryRows(rows: any[], sort?: InventoryListSort | null): any[] {
  const spec = normalizeInventoryListSort(sort);
  if (!spec) return rows;
  const dir = spec.order === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const va = inventorySortValue(a, spec.sortBy);
    const vb = inventorySortValue(b, spec.sortBy);
    if (va !== vb) return (va - vb) * dir;
    return String(a?.id ?? "").localeCompare(String(b?.id ?? ""));
  });
}

export function loadProductsPageFromDisk(
  page = 1,
  pageSize = 50,
  search = "",
  sort?: InventoryListSort | null,
): {
  products: any[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
  hasMore: boolean;
} {
  const all = readProductsFromDisk();
  const q = normalizeProductSearchText(search);
  const filtered = q ? all.filter((p) => productRowMatchesSearch(p, search)) : all;
  const sorted = sortInventoryRows(filtered, sort);
  const safePage = Math.max(1, Math.floor(Number(page) || 1));
  const safeSize = Math.min(50, Math.max(1, Math.floor(Number(pageSize) || 50)));
  const total = sorted.length;
  const totalPages = Math.max(1, Math.ceil(Math.max(0, total) / safeSize) || 1);
  const currentPage = Math.min(safePage, totalPages);
  const start = (currentPage - 1) * safeSize;
  return {
    products: sorted.slice(start, start + safeSize),
    total,
    page: currentPage,
    pageSize: safeSize,
    totalPages,
    hasMore: currentPage < totalPages,
  };
}

function productMatchKeys(p: any): string[] {
  const keys = [
    p?.id,
    p?.sku,
    p?.shopeeItemId,
    p?.shopeeModelId,
    p?.barcode,
  ];
  for (const c of Array.isArray(p?.children) ? p.children : []) {
    keys.push(c?.id, c?.sku, c?.shopeeModelId);
  }
  for (const c of Array.isArray(p?.children_models) ? p.children_models : []) {
    keys.push(c?.id, c?.sku, c?.shopeeModelId);
  }
  return keys.map((k) => String(k || "").trim()).filter(Boolean);
}

export function loadProductByIdFromDisk(productId: string): any | null {
  const id = String(productId || "").trim();
  if (!id) return null;
  const all = readProductsFromDisk();
  for (const p of all) {
    if (String(p.id || "").trim() === id) return p;
    if (String(p.shopeeItemId || "").trim() === id) return p;
    if (String(p.shopeeModelId || "").trim() === id) return p;
    for (const key of ["children", "children_models"] as const) {
      const list = Array.isArray(p[key]) ? p[key] : [];
      const child = list.find(
        (c: any) =>
          String(c?.id || "").trim() === id ||
          String(c?.shopeeModelId || "").trim() === id,
      );
      if (child) {
        return inheritShopeeLinkFromParent(child, p);
      }
    }
  }
  return null;
}

export function loadProductsByIdsFromDisk(
  productIds: string[],
  shopeeItemIds: string[] = [],
): any[] {
  const wanted = new Set(
    [...productIds, ...shopeeItemIds].map((v) => String(v || "").trim()).filter(Boolean),
  );
  if (wanted.size === 0) return [];
  return readProductsFromDisk().filter((p) =>
    productMatchKeys(p).some((k) => wanted.has(k) || wanted.has(`shopee-item-${k}`)),
  );
}

export function searchProductsFromDisk(query: string, limit = 40): any[] {
  const q = normalizeProductSearchText(query);
  const safeLimit = Math.min(100, Math.max(1, Math.floor(Number(limit) || 40)));
  const all = readProductsFromDisk();
  if (!q) return all.slice(0, safeLimit);

  const scored: Array<{ p: any; score: number }> = [];
  for (const p of all) {
    if (!productRowMatchesSearch(p, query)) continue;
    const sku = normalizeProductSearchText(p.sku);
    const title = normalizeProductSearchText(p.title);
    let score = 0;
    if (sku === q) score = 300;
    else if (sku.startsWith(q)) score = 200;
    else if (sku.includes(q)) score = 120;
    else if (title.includes(q)) score = 80;
    else score = 90;
    scored.push({ p, score });
  }
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, safeLimit).map((x) => x.p);
}

export async function applyImportStockAndPriceOnDisk(
  productId: string,
  quantityDelta: number,
  importPrice: number,
  opts?: { skuHint?: string },
): Promise<{
  product: any;
  oldStock: number;
  newStock: number;
  oldImportPrice: number;
  newImportPrice: number;
  target: "parent" | "child";
  parentId?: string;
  warehouse: "KhoGoc";
  collection: "products";
}> {
  const id = String(productId || "").trim();
  const skuHint = String(opts?.skuHint || "").trim();
  if (!id && !skuHint) throw new Error("Thiếu productId/sku để cập nhật Kho Gốc");
  const qty = Math.round(Number(quantityDelta) || 0);
  const price = Math.max(0, Math.round(Number(importPrice) || 0));

  const all = readProductsFromDisk();
  let parentIdx = -1;
  let mode: "parent" | "child" = "parent";
  let childKey: "children" | "children_models" | null = null;
  let childIdx = -1;

  for (let i = 0; i < all.length; i++) {
    const p = all[i];
    const parentMatch =
      (id && String(p.id || "").trim() === id) ||
      (skuHint && String(p.sku || "").trim().toLowerCase() === skuHint.toLowerCase());
    const cKey: "children" | "children_models" | null =
      Array.isArray(p.children) && p.children.length
        ? "children"
        : Array.isArray(p.children_models) && p.children_models.length
          ? "children_models"
          : null;
    if (cKey) {
      const children = p[cKey] as any[];
      const cIdx = children.findIndex((c) => {
        const cid = String(c?.id || c?.shopeeModelId || "").trim();
        const csku = String(c?.sku || "").trim();
        return (id && cid === id) || (skuHint && csku.toLowerCase() === skuHint.toLowerCase());
      });
      if (cIdx >= 0) {
        parentIdx = i;
        mode = "child";
        childKey = cKey;
        childIdx = cIdx;
        break;
      }
    }
    if (parentMatch) {
      parentIdx = i;
      childKey = cKey;
      break;
    }
  }

  if (parentIdx < 0) {
    throw new Error(
      `Không tìm thấy sản phẩm trong Kho Gốc (disk). id=${id || "—"} sku=${skuHint || "—"}`,
    );
  }

  const parent = { ...all[parentIdx], id: String(all[parentIdx].id) };
  let productOut: any;
  let oldStock = 0;
  let newStock = 0;
  let oldImportPrice = 0;

  if (mode === "child" && childKey && childIdx >= 0) {
    const children = [...(parent[childKey] as any[])];
    const before = children[childIdx];
    oldStock = Math.max(0, Math.round(Number(before.stock) || 0));
    oldImportPrice = Math.max(0, Math.round(Number(before.importPrice) || 0));
    newStock = Math.max(0, oldStock + qty);
    const mergedChild = {
      ...before,
      id: before.id || id,
      stock: newStock,
      importPrice: price,
      status:
        newStock <= 0 && before.status !== "draft"
          ? "out_of_stock"
          : before.status === "out_of_stock"
            ? "active"
            : before.status,
      lastSynced: new Date().toISOString(),
    };
    children[childIdx] = mergedChild;
    const totalStock = children.reduce(
      (s, c) => s + Math.max(0, Math.round(Number(c.stock) || 0)),
      0,
    );
    all[parentIdx] = {
      ...parent,
      [childKey]: children,
      stock: totalStock,
      lastSynced: new Date().toISOString(),
    };
    productOut = mergedChild;
  } else {
    oldStock = Math.max(0, Math.round(Number(parent.stock) || 0));
    oldImportPrice = Math.max(0, Math.round(Number(parent.importPrice) || 0));
    newStock = Math.max(0, oldStock + qty);
    productOut = {
      ...parent,
      stock: newStock,
      importPrice: price,
      status:
        newStock <= 0 && parent.status !== "draft"
          ? "out_of_stock"
          : parent.status === "out_of_stock"
            ? "active"
            : parent.status,
      lastSynced: new Date().toISOString(),
    };
    all[parentIdx] = productOut;
  }

  await saveProductsToDisk(all);
  return {
    product: productOut,
    oldStock,
    newStock,
    oldImportPrice,
    newImportPrice: price,
    target: mode,
    parentId: String(parent.id),
    warehouse: "KhoGoc",
    collection: "products",
  };
}
